from html.parser import HTMLParser
from pathlib import Path
import hashlib, json, re

class VisibleText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style', 'noscript'}:
            self.hidden += 1
        if tag in {'p', 'div', 'li', 'br', 'h1', 'h2', 'h3', 'h4', 'section'}:
            self.parts.append('\n')

    def handle_endtag(self, tag):
        if tag in {'script', 'style', 'noscript'} and self.hidden:
            self.hidden -= 1
        if tag in {'p', 'div', 'li', 'h1', 'h2', 'h3', 'h4', 'section'}:
            self.parts.append('\n')

    def handle_data(self, data):
        if not self.hidden:
            self.parts.append(data)

base = Path('products/services/catalogue-kofi')
raw = (base / 'raw/terms.html').read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == 'b00e96a3be22e72cc2a5c7c0436fb5c51ec9cc48783b7c49fd005203e0c1d701'
parser = VisibleText()
parser.feed(raw.decode('utf-8'))
lines = list(dict.fromkeys(' '.join(line.split()) for line in ''.join(parser.parts).splitlines() if line.strip()))
patterns = {
    'ai_and_rights': r'artificial intelligence|generative|\bAI\b|intellectual property|copyright|prohibited',
    'offer_and_delivery': r'commission|digital (?:goods|products|content|downloads)|shop items|refund|delivery',
    'seller_and_settlement': r'Canada|Stripe|PayPal|payout|transaction fee|service fee|platform fee|payment processor',
}
report = {'source': 'https://more.ko-fi.com/terms', 'fetch_receipt': 'TASK-179517270100', 'sha256': digest, 'method': 'Keyword excerpts from parsed HTML text with whitespace normalized. Missing matches leave the condition unresolved.', 'excerpts': {topic: [line for line in lines if re.search(pattern, line, re.I)] for topic, pattern in patterns.items()}}
output = json.dumps(report, ensure_ascii=False, indent=2) + '\n'
(base / 'terms-excerpts.json').write_text(output, encoding='utf-8')
print(json.dumps({topic: len(excerpts) for topic, excerpts in report['excerpts'].items()}))
